    for i in range(1, limitSize):
        for j in range(i & 1, i + 1, 2):
            if j == 0:
                tableDP[i][j] = tableDP[i - 1][j + 1]
                if checkOK[i - 1][j + 1] == 1:
                    tableDP[i][j] = (tableDP[i][j] + 1) % MOD_CONST
                else:
                    checkOK[i][j] = 1
                continue
            tableDP[i][j] = (tableDP[i - 1][j - 1] + tableDP[i - 1][j + 1]) % MOD_CONST
            if checkOK[i - 1][j + 1] == 1 or checkOK[i - 1][j - 1] == 1:
                tableDP[i][j] = (tableDP[i][j] + 1) % MOD_CONST
            else:
                checkOK[i][j] = 1
    print(tableDP[2 * nInput][0])

if __name__ == "__main__":
    main()

